using System.Security.Cryptography;using System.Text;using System.Text.Json;using Microsoft.CodeAnalysis;using Microsoft.CodeAnalysis.CSharp;using Microsoft.CodeAnalysis.CSharp.Syntax;
if(args.Length<3)throw new ArgumentException("root, project, and files are required");var root=Path.GetFullPath(args[0]);var project=args[1];var files=args.Skip(2).ToArray();var trees=new List<SyntaxTree>();var contents=new Dictionary<string,string>();string Hash(string value)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value))).ToLowerInvariant();
foreach(var relative in files){var target=Path.GetFullPath(Path.Combine(root,relative));if(!target.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Analysis path escapes project root.");var content=File.ReadAllText(target);contents[relative]=content;trees.Add(CSharpSyntaxTree.ParseText(content,path:relative));}
var refs=new[]{MetadataReference.CreateFromFile(typeof(object).Assembly.Location),MetadataReference.CreateFromFile(typeof(Console).Assembly.Location),MetadataReference.CreateFromFile(typeof(Enumerable).Assembly.Location)};var compilation=CSharpCompilation.Create("CrucibleSemantic",trees,refs,new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));var functions=new List<Dictionary<string,object?>>();var calls=new List<Dictionary<string,object?>>();var findings=new List<Dictionary<string,object?>>();var ids=new Dictionary<IMethodSymbol,string>(SymbolEqualityComparer.Default);var sourceNames=new HashSet<string>(StringComparer.OrdinalIgnoreCase){"request","req","body","query","params","input","userInput"};var sinkNames=new HashSet<string>(StringComparer.OrdinalIgnoreCase){"Start","Execute","Query","WriteAllText","Deserialize"};
foreach(var tree in trees){var model=compilation.GetSemanticModel(tree);var relative=tree.FilePath;foreach(var method in tree.GetRoot().DescendantNodes().OfType<MethodDeclarationSyntax>()){var symbol=model.GetDeclaredSymbol(method);if(symbol is null)continue;var id=$"{relative}#{symbol.ToDisplayString()}";ids[symbol.OriginalDefinition]=id;functions.Add(new(){["id"]=id,["file"]=relative,["start"]=method.SpanStart,["end"]=method.Span.End,["parameters"]=method.ParameterList.Parameters.Select(p=>p.Identifier.Text).ToArray(),["sources"]=method.ParameterList.Parameters.Where(p=>sourceNames.Contains(p.Identifier.Text)).Select(p=>new{ name=p.Identifier.Text,start=p.SpanStart}).ToArray(),["sinks"]=Array.Empty<object>()});}}
foreach(var tree in trees){var model=compilation.GetSemanticModel(tree);var relative=tree.FilePath;var content=contents[relative];foreach(var call in tree.GetRoot().DescendantNodes().OfType<InvocationExpressionSyntax>()){var enclosing=model.GetEnclosingSymbol(call.SpanStart) as IMethodSymbol;var symbol=model.GetSymbolInfo(call).Symbol as IMethodSymbol;var name=symbol?.Name??call.Expression.ToString();ids.TryGetValue(symbol?.OriginalDefinition!,out var target);var caller=enclosing is null?null:ids.GetValueOrDefault(enclosing.OriginalDefinition);calls.Add(new(){["caller"]=caller,["calleeText"]=name,["target"]=target,["file"]=relative,["start"]=call.SpanStart,["end"]=call.Span.End});if(sinkNames.Contains(name)){findings.Add(new(){["schemaVersion"]=1,["projectId"]=project,["language"]="csharp",["kind"]="semantic-security-sink",["file"]=relative,["boundary"]=$"{relative}:{call.SpanStart}-{call.Span.End}",["start"]=call.SpanStart,["end"]=call.Span.End,["baseSha256"]=Hash(content),["toolId"]="roslyn",["toolVersion"]=typeof(CSharpCompilation).Assembly.GetName().Version?.ToString()??"unknown",["callee"]=name,["proofStageSatisfied"]=false,["promotionAuthorized"]=false});}}}
var diagnostics=compilation.GetDiagnostics().Select(d=>new{code=d.Id,severity=d.Severity.ToString(),message=d.GetMessage(),file=d.Location.SourceTree?.FilePath,start=d.Location.IsInSource?d.Location.SourceSpan.Start:(int?)null}).ToArray();var result=new{schemaVersion=1,projectId=project,adapter=new{id="roslyn",version=typeof(CSharpCompilation).Assembly.GetName().Version?.ToString()},files=contents.Select(kv=>new{file=kv.Key,sha256=Hash(kv.Value)}),diagnostics,functions,calls,interproceduralPaths=Array.Empty<object>(),findings};Console.Write(JsonSerializer.Serialize(result));
